from django.utils import timezone


def close_duplicate_open_sessions(apps, schema_editor):
    """Deja abierta solo la sesión más reciente para que el UniqueConstraint pueda crearse."""
    CashSession = apps.get_model('finance', 'CashSession')
    open_ids = list(CashSession.objects.filter(is_open=True).order_by('-id').values_list('id', flat=True))
    for session in CashSession.objects.filter(id__in=open_ids[1:]):
        session.is_open = False
        session.end_date = session.end_date or timezone.now()
        session.notes = ((session.notes or '') + ' [Cerrada automáticamente: caja abierta duplicada]').strip()
        session.save(update_fields=['is_open', 'end_date', 'notes'])


